def free_only_reason(model: dict[str, Any]) -> str:
    status = classify_free_status(model)
    if status == "FREE":
        return "explicit_or_implicit_free_metadata"
    if status == "PAID":
        return "paid_or_nonzero_pricing"
    return "pricing_unknown_fail_closed"

